use super::contracts::*;
use std::{path::Path, sync::atomic::AtomicBool};

#[derive(Clone, Debug, Eq, PartialEq)] pub struct AuthorityPreparation{pub profile_user:Vec<u8>,pub durable_session_id:Vec<u8>,pub workspace_root:Vec<u8>,pub cwd:Vec<u8>,pub transport_role:TransportRole,pub backend:Backend,pub actor:ActorRole,pub controls:AllowedControls,pub lifetime:TerminalLifetime,pub repeated_probes:Vec<RepeatedProbeAuthority>,pub direct_human_model_read_only:bool}
#[derive(Clone, Debug, Eq, PartialEq)] pub struct PreparedAuthority{pub persistence:StartPersistence} impl PreparedAuthority{pub fn view(&self)->&StartPersistence{&self.persistence}}
#[derive(Clone, Debug, Eq, PartialEq)] pub struct OwnedAuthorityClaim{pub value:AuthorityClaim,pub controls:AllowedControls} impl OwnedAuthorityClaim{pub fn view(&self)->&AuthorityClaim{&self.value}}
#[derive(Clone, Debug, Eq, PartialEq)] pub struct OwnedOwnerCatalogClaim{pub value:OwnerCatalogAuthorityClaim} impl OwnedOwnerCatalogClaim{pub fn view(&self)->&OwnerCatalogAuthorityClaim{&self.value}}

fn proof()->HolderProof{use std::io::Read;let mut bytes=[0;32];if let Ok(mut f)=std::fs::File::open("/dev/urandom"){let _=f.read_exact(&mut bytes);}if bytes.iter().all(|&b|b==0){bytes[0]=1}HolderProof{bytes}}
pub fn prepare_start_persistence(input:AuthorityPreparation)->Result<PreparedAuthority>{if !Path::new(std::str::from_utf8(&input.workspace_root).unwrap_or("")).is_absolute()||!Path::new(std::str::from_utf8(&input.cwd).unwrap_or("")).is_absolute(){return Err(Error::InvalidPrincipal)}let persistence=StartPersistence{grant:AuthorityGrant{principal:Principal{profile_user:input.profile_user,durable_session_id:input.durable_session_id,workspace_root:input.workspace_root,cwd:input.cwd,transport_role:input.transport_role,backend:input.backend,lifetime:input.lifetime},actor:input.actor,controls:input.controls,generation:AuthorityGeneration::init(1)?,repeated_probes:input.repeated_probes},proof:proof(),direct_human_model_read_only:input.direct_human_model_read_only};persistence.grant.principal.validate()?;if !persistence.grant.controls.any(){return Err(Error::InvalidAuthorityGrant)}Ok(PreparedAuthority{persistence})}
pub fn own_authority_claim(authority_claim:AuthorityClaim,controls:AllowedControls)->Result<OwnedAuthorityClaim>{authority_claim.validate()?;if !controls.any(){return Err(Error::InvalidAuthorityGrant)}Ok(OwnedAuthorityClaim{value:authority_claim,controls})}
pub fn own_owner_catalog_claim(c:OwnerCatalogAuthorityClaim)->Result<OwnedOwnerCatalogClaim>{if c.proof.bytes.iter().all(|&b|b==0){return Err(Error::InvalidAuthorityClaim)}Ok(OwnedOwnerCatalogClaim{value:c})}
#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub enum ValidationError{Contract(Error),MissingTerminalAuthority} impl From<Error>for ValidationError{fn from(e:Error)->Self{Self::Contract(e)}}
pub fn validate(r:&ActionRequest)->std::result::Result<(),ValidationError>{r.validate()?;match r{ActionRequest::Start(s)if s.persistence.is_none()=>Err(ValidationError::MissingTerminalAuthority),ActionRequest::List(x)if x.owner_authority.is_none()=>Err(ValidationError::MissingTerminalAuthority),ActionRequest::Start(_)|ActionRequest::List(_)=>Ok(()),_ if claim(r).is_none()=>Err(ValidationError::MissingTerminalAuthority),_=>Ok(())}}
pub fn claim(r:&ActionRequest)->Option<&AuthorityClaim>{authority_claim(r)}
pub fn attach_process_owner(r:&mut ActionRequest,owner:ProcessOwner){let target=match r{ActionRequest::Read(x)=>&mut x.authority,ActionRequest::Screen(x)=>&mut x.authority,ActionRequest::Write(x)=>&mut x.authority,ActionRequest::Wait(x)=>&mut x.authority,ActionRequest::Monitor(x)=>&mut x.authority,ActionRequest::Inspect(x)=>&mut x.authority,ActionRequest::Resize(x)=>&mut x.authority,ActionRequest::Signal(x)=>&mut x.authority,ActionRequest::Close(x)=>&mut x.authority,_=>return};if let Some(c)=target{c.process_owner=Some(owner)}}
pub fn authority_session_id(r:&ActionRequest)->Option<&[u8]>{match r{ActionRequest::Read(x)=>Some(&x.session_id),ActionRequest::Screen(x)=>Some(&x.session_id),ActionRequest::Write(x)=>Some(&x.session_id),ActionRequest::Wait(x)=>Some(&x.session_id),ActionRequest::Monitor(x)=>Some(&x.session_id),ActionRequest::Inspect(x)=>Some(&x.session_id),ActionRequest::Resize(x)=>Some(&x.session_id),ActionRequest::Signal(x)=>Some(&x.session_id),ActionRequest::Close(x)=>Some(&x.session_id),_=>None}}
pub fn requires_ordered_mutation(r:&ActionRequest)->bool{matches!(r,ActionRequest::Write(_)|ActionRequest::Monitor(_)|ActionRequest::Resize(_)|ActionRequest::Signal(_)|ActionRequest::Close(_))||matches!(r,ActionRequest::Inspect(x)if x.acknowledge_event_id.is_some())}
pub trait BackendExecutor{type Output;fn execute_authorized(&mut self,request:ActionRequest,cancelled:&AtomicBool)->std::result::Result<Self::Output,ValidationError>;}
pub fn execute<B:BackendExecutor>(backend:&mut B,request:ActionRequest,cancelled:&AtomicBool)->std::result::Result<B::Output,ValidationError>{validate(&request)?;backend.execute_authorized(request,cancelled)}

#[cfg(test)]mod tests{use super::*;fn request()->ActionRequest{ActionRequest::Screen(SessionRequest{session_id:b"terminal-1".to_vec(),authority:None,after_event_id:0,acknowledge_event_id:None,max_events:64})}#[test]fn private_validation_requires_authority(){assert_eq!(validate(&request()),Err(ValidationError::MissingTerminalAuthority))}#[test]fn mutation_order(){let mut r=request();if let ActionRequest::Screen(x)=&mut r{x.acknowledge_event_id=Some(1)}assert!(!requires_ordered_mutation(&r));let w=ActionRequest::Write(WriteRequest{session_id:b"x".to_vec(),payload:Some(WritePayload::Text(b"x".to_vec())),lease:WriteLeaseIntent::Use,authority:None});assert!(requires_ordered_mutation(&w))}}
